import json
import requests
import chardet
API_URL = "http://api.example.com/data"
def task_func(url=API_URL, from_encoding=None, to_encoding="utf8"):
    response = requests.get(url, timeout=5)
    content = response.content
    if not content:
        return {}
    encoding = from_encoding or chardet.detect(content).get('encoding')
    if not encoding:
        raise ValueError("Unable to detect encoding for non-empty content")
    try:
        text = content.decode(encoding)
    except Exception:
        text = content.decode(encoding, errors='replace')
    text = text.lstrip('\ufeff')
    try:
        normalized_bytes = text.encode(to_encoding)
    except Exception:
        normalized_bytes = text.encode(to_encoding, errors='replace')
    try:
        normalized_text = normalized_bytes.decode(to_encoding)
    except Exception:
        normalized_text = normalized_bytes.decode(to_encoding, errors='replace')
    data = json.loads(normalized_text)
    return data

