    def traverse(obj):
        if isinstance(obj, dict):
            for v in obj.values():
                traverse(v)
        elif isinstance(obj, (list, tuple)):
            for item in obj:
                traverse(item)
        elif isinstance(obj, str):
            urls.extend(url_pattern.findall(obj))
    traverse(data)
    counts = Counter(urls)
    if top_n is None:
        return dict(counts)
    if top_n <= 0:
        return {}
    return dict(counts.most_common(top_n))

