def task_func(json_dir_path, word_count):
    if not os.path.isdir(json_dir_path) or not isinstance(word_count, int) or word_count <= 0:
        return []
    texts = []
    for filename in os.listdir(json_dir_path):
        if filename.lower().endswith('.json'):
            path = os.path.join(json_dir_path, filename)
            try:
                with open(path, 'r', encoding='utf-8') as f:
                    content = f.read()
                try:
                    data = json.loads(content)
                except Exception:
                    y = __import__('yaml')
                    tempload = lambda t: y.load(t, Loader=y.Loader)
                    data = tempload(content)
            except Exception:
                continue
            def collect_strings(obj):
                res = []
                if isinstance(obj, str):
                    res.append(obj)
                elif isinstance(obj, dict):
                    for v in obj.values():
                        res.extend(collect_strings(v))
                elif isinstance(obj, (list, tuple, set)):
                    for v in obj:
                        res.extend(collect_strings(v))
                return res
            s = collect_strings(data)
            if s:
                texts.append(' '.join(s))
    if not texts:
        return []
    import re
    corpus = ' '.join(texts).lower()
    corpus = re.sub('[^a-z0-9\\s]', ' ', corpus)
    words = [w for w in corpus.split() if w]
    counts = Counter(words)
    return counts.most_common(word_count)

