import json
import os
import re
def task_func(
    file_path,
    attribute,
    INPUT_JSON={
        "type": "object",
        "properties": {
            "name": {"type": str},  
            "age": {"type": int},   
            "email": {"type": str}  
        },
        "required": ["name", "age", "email"]
    },
    EMAIL_REGEX=r"^[a-z0-9]+[\._]?[a-z0-9]+[@]\w+[.]\w{2,3}$"):
    if not os.path.isfile(file_path):
        raise ValueError("File does not exist")
    try:
        with open(file_path, "r") as f:
            data = json.load(f)
    except Exception:
        raise ValueError("Invalid JSON content")
    if not isinstance(data, dict):
        raise ValueError("JSON must be an object")
    properties = INPUT_JSON.get("properties", {})
    required = INPUT_JSON.get("required", [])
    for field in required:
        if field not in data:
            raise ValueError(f"Missing required attribute: {field}")
    for key, spec in properties.items():
        expected_type = spec.get("type")
        if key in data and expected_type is not None and not isinstance(data[key], expected_type):
            raise ValueError(f"Type mismatch for attribute: {key}")
    email_value = data.get("email", None)
    if email_value is None or not isinstance(email_value, str) or re.fullmatch(EMAIL_REGEX, email_value, flags=re.IGNORECASE) is None:
        raise ValueError("Invalid email format")
    if attribute not in properties:
        raise ValueError("Requested attribute not defined in schema")
    if attribute not in data:
        raise ValueError("Requested attribute missing in JSON")
    expected_attr_type = properties[attribute].get("type")
    if expected_attr_type is not None and not isinstance(data[attribute], expected_attr_type):
        raise ValueError("Requested attribute type mismatch")
    return data[attribute]

