        return None
    def normalize_value(v):
        if isinstance(v, bool):
            return v
        if isinstance(v, (int, float)):
            return float(v) * 2.0
        if isinstance(v, str):
            n = str_to_number(v)
            return n * 2.0 if n is not None else v
        if isinstance(v, (list, tuple)):
            out = []
            for x in v:
                if isinstance(x, bool):
                    out.append(x)
                elif isinstance(x, (int, float)):
                    out.append(float(x) * 2.0)
                elif isinstance(x, str):
                    n = str_to_number(x)
                    out.append(n * 2.0 if n is not None else x)
                else:
                    out.append(x)
            return out
